      const target = doc?.querySelector('.container') || doc?.body;
      if (!target) throw new Error('PDF layout has no document body.');

      const captureWidth = Math.ceil(
        Math.max(target.scrollWidth, target.offsetWidth, target.getBoundingClientRect().width, 600),
      );
      const scrollHeight = Math.ceil(
        Math.max(
          target.scrollHeight,
          target.offsetHeight,
          doc.documentElement.scrollHeight,
          100,
        ),
      );
